from openpyxl import load_workbook

wb = load_workbook('budget.xlsx', data_only=False)
ws = wb['Budget']
print("Formulas / values per row:")
for row in ws.iter_rows(min_row=1, max_row=25, max_col=3):
    for c in row:
        if c.value is not None:
            print(c.coordinate, repr(c.value), "| fmt:", c.number_format)

wbv = load_workbook('budget.xlsx', data_only=True)
wsv = wbv['Budget']
print("\nCached computed values:")
for row in wsv.iter_rows(min_row=1, max_row=25, max_col=3):
    for c in row:
        if c.value is not None:
            print(c.coordinate, repr(c.value))

